mapper.insert:
INSERT INTO pet_daily_counters (
    account_id, counter_date, counter, value, updated_at
) VALUES (
    #{accountId}, #{counterDate}, #{counter}, 1, #{updatedAt}
)
ON CONFLICT(account_id, counter_date, counter) DO UPDATE
SET value = value + 1,
    updated_at = #{updatedAt}
WHERE value < #{limit}

INSERT INTO pet_daily_counters (
    account_id, counter_date, counter, value, updated_at
) VALUES (
    #{accountId}, #{counterDate}, #{counter}, #{amount}, #{updatedAt}
)
ON CONFLICT(account_id, counter_date, counter) DO UPDATE
SET value = value + #{amount},
    updated_at = #{updatedAt}
WHERE value + #{amount} <= #{limit}
